def algorithm(func, dim, lb, ub, budget, rng):
    def bound(x):
        return np.clip(x, lb, ub)

    pop_size = 100
    pop = rng.uniform(lb, ub, (pop_size, dim))
    fitnesses = [func(bound(individual)) for individual in pop]

    for _ in range(budget):
        parents = []
        for _ in range(pop_size):
            idx1, idx2 = np.random.choice(pop_size, 2, replace=False)
            parent = bound(0.5 * pop[idx1] + 0.5 * pop[idx2])
            parents.append(parent)

        next_gen = []
        for parent in parents:
            child = parent.copy()
            for i in range(dim):
                if rng.random() < 0.01:  # mutation probability
                    child[i] += rng.uniform(-1, 1)
                if rng.random() < 0.05:  # crossover probability
                    idx2 = np.random.choice(pop_size)
                    parent2 = bound(0.5 * pop[idx2] + 0.5 * parent)
                    child[i] = (parent[i] + parent2[i]) / 2
            next_gen.append(bound(child))

        fitnesses = [func(individual) for individual in next_gen]
        idx_best = np.argmin(fitnesses)
        if fitnesses[idx_best] < fitnesses[np.argmin(fitnesses)]:
            pop = next_gen
            fitnesses = fitnesses
    return bound(pop[np.argmin(fitnesses)])

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate):
        return np.clip(candidate, lb, ub)

    def initial_candidate():
        candidate = np.zeros(dim)
        for i in range(dim):
            candidate[i] = rng.uniform(lb, ub)
        return candidate

    current_candidate = initial_candidate()
    best_candidate = current_candidate.copy()
    current_fitness = func(current_candidate)

    # Simulated Annealing
    temperature = 1.0
    cooling_rate = 0.99
    for i in range(budget):
        new_candidate = clip(current_candidate + rng.normal(size=dim, loc=0, scale=temperature))
        new_fitness = func(new_candidate)

        if new_fitness < current_fitness:
            current_candidate = new_candidate
            current_fitness = new_fitness

            # Update best candidate if necessary
            if new_fitness < func(best_candidate):
                best_candidate = new_candidate.copy()
                current_candidate = best_candidate

        temperature *= cooling_rate

    return best_candidate
